<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main test hlcon">
            <div v-if="loading" class="loads">
                <van-loading size="20px" type="spinner"/>
            </div>
            <div  class="tab-list-lot" @click="optabs">
                <div class="tab-list-lot-t">{{lotName}}</div>
                <img src="@/assets/images/yx_xla.webp">
            </div>
            <div  class="men-t">
                <div class="men-t-1">
                    <van-field
                            class="input"
                            style="width:75px;margin-left: 5px;margin-right: 10px;height:25px;line-height:20px;"
                            type="number"
                            size="mini"
                            :border="true"
                            v-model="quickAmout"
                            placeholder="输入赔率"
                    />
                    <img v-if="quickStatus==1" @click="swTabs(2)" class="men1-img" src="@/assets/images/swqy.svg">
                    <img v-if="quickStatus==2" @click="swTabs(1)" class="men1-img" src="@/assets/images/swjy.svg">
                    <div  class="mbtns" @click="quickSet" >套用</div>
                </div>
                <div style="overflow:auto;padding-bottom:10px">
                    <table style="width:200%" >
                        <thead>
                            <tr>
                                <th rowspan="2">位置1</th>
                                <th rowspan="2">位置2</th>
                                <th colspan="2">第一阶段(一次性)</th>
                                <th colspan="2">第二阶段(累进)</th>
                                <th rowspan="2">最大降倍</th>
                            </tr>
                            <tr>
                                <th>金额(实货量)</th>
                                <th>降赔率</th>
                                <th>金额(实货量)</th>
                                <th>降赔率</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="(item,index2) in betmoneyodds_list" :key="index2" :class="(index2%2==0)?'eve':'old'">
                                <td >
                                    <van-stepper disabled :show-minus="false" :show-plus="false" :min="0" integer  @keyup.native="check_count" v-model="item.firstCount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0" integer  @keyup.native="check_count" v-model="item.secountCount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0" integer  @keyup.native="check_count" v-model="item.firstDownAmount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"   v-model="item.firstDownOdds"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"   @keyup.native="check_count" v-model="item.everyDownAmount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"    v-model="item.everyDownOdds"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"    v-model="item.maxDown"></van-stepper>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
            <div class="zdbh-btns">
                <div @click="savebetmoney" class="zdbh-btns-sub">确定</div>
            </div>
        </div>
        <van-popup v-model:show="showLottery" position="bottom" class="popTop" >
            <div class="pop-list">
                <div class="pop-line">
                    <div class="pop-lines">
                        <div class="pop-list-line"></div>
                    </div>
                    <div class="pop-head">
                        <div class="pop-head-t">彩种选择</div>
                        <div @click="showLottery=false" class="pop-head-img">关闭</div>
                    </div>
                </div>
                <div class="pop-cont">
                    <div class="flex-item">
                        <div class="yx-select" @click="onConfirm(item)" :class="item.id==lotId?'active':''" v-for="item in lotList" :key="item.id">{{item.name}}</div>
                    </div> 
                </div>
            </div>
        </van-popup>
    </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const betmoneyodds_list = ref([])
const loading = ref(false)
const quickAmout = ref("")
const quickStatus = ref('2')
const lotList = ref([])
const lotName = ref('')
const lotId = ref('')
const num = ref(3)
const tits = ref('控盘降倍')
const showLottery = ref(false)
const transferMoney = ref('') // 补充定义，用于check_count
// Methods
const optabs = () => {
  showLottery.value = true
}
const onConfirm = (its) => {
  lotName.value = its.name
  lotId.value = its.id
  showLottery.value = false
  getbetmoney()
}
const getLot = async () => {
  try {
    const res = await userStore.getLotList()
    lotList.value = res.data
    lotId.value = res.data[0].id
    lotName.value = res.data[0].name
    await getbetmoney()
  } catch (error) {
    console.error('获取彩种失败:', error)
  }
}
const check_count = (e) => {
  let obj = e.target
  if (obj.value != '' && obj.value.substr(0, 1) == '.') {
    obj.value = 0
  }
  if (!obj.value) {
    obj.value = 0
  }
  obj.value = obj.value.replace(/^0*(0\.|[1-9])/, '$1')
  obj.value = obj.value.replace(/^(\-)*(\d+)\.(\d\d\d\d).*$/, '$1$2.$3')
  if (obj.value.indexOf(".") < 0 && obj.value != "") {
    if (obj.value.substr(0, 1) == '0' && obj.value.length == 2) {
      obj.value = obj.value.substr(1, obj.value.length)
    }
  }
  transferMoney.value = obj.value
}
const swTabs = async(num) => {
    quickStatus.value = num
    let type = '';
    let str = {
        lotteryId:lotId.value,
        downOddsType:2,
        openFlag:num
    }
    try {
        loading.value = true
        const res = await userStore.setDwonMkOpenFlag(str);
        loading.value = false
        getbetmoney()
    } catch (error) {
        loading.value = false
        console.log('获取游戏信息失败')
    } 
}

const ktswTabs = (item, num) => {
  item.status = num
}

const zstabs = (item) => {
  item.selected = !item.selected
}

const quickSet = () => {
  betmoneyodds_list.value.forEach(item => {
    item.firstDownOdds  = quickAmout.value
    item.everyDownOdds  = quickAmout.value
  })
}

const getbetmoney = async () => {
  loading.value = true
  try {
    let str = {
        lotteryId:lotId.value,
        downOddsType:2
    }
    const res = await userStore.queryMkDownOdds(str)
    res.data.map(iten => {
      iten.selected = true
    })
    betmoneyodds_list.value = res.data
  } catch (error) {
    console.error('获取赔率设置失败:', error)
  } finally {
    loading.value = false
  }
}

const savebetmoney = async () => {
  try {
    const res = await userStore.downMkOddsSave(betmoneyodds_list.value)
    // 假设您有一个toast组件或方法
    if (res.code == 200) {
      // 成功提示
      console.log('保存成功:', res.message)
      await getbetmoney()
    } else {
      // 失败提示
      console.error('保存失败:', res.message)
    }
  } catch (error) {
    console.error('保存赔率设置失败:', error)
  }
}

// Lifecycle
onMounted(() => {
  getLot()
})
</script>
<style lang="less" scoped>
.hlcon :deep(.van-stepper__input){
    width:80px !important;
    height: 35px !important;
    line-height: 35px !important;
    background: #FFFFFF 0% 0% no-repeat padding-box;
    border: 1px solid #D0D0D0;
    border-radius: 10px;
    font-size: 16px;
}
.hlcon :deep(.van-tab__text){
    font-size: 14px;
    font-weight: normal;
    color: var(--grey-blue-surface-g-300);
}
.hlcon :deep(.van-tab--active .van-tab__text){
   color: var(--blue-normal);
}
.tab-list-lot{
    width: 85%;
    height: 40px;
    line-height: 40px;
    border: solid 0.3px var(--grey-blue-surface-g-50);
    background-color: var(--white-white);
    border-radius: 10px;
    margin: 0 auto;
    margin-top:10px;
    font-size: 16px;
    font-weight: normal;
    line-height: 40px;
    letter-spacing: 0px;
    color: var(--grey-blue-surface-g-700);
    display: flex;
    align-items: center;
    cursor: pointer;
    margin-bottom: 10px;
    .tab-list-lot-t{
        flex: 1;
        margin-left: 20px;
    }
    img{
        width: 20px;
        height: 20px;
        margin-right: 15px;
    }
}
</style>